class Solution {
    vector<string> res;
    string num;
    long long target;
    int n;

    void backtrack(int pos, long long val, long long prev, string& expr) {
        if (pos == n) {
            if (val == target) res.push_back(expr);
            return;
        }
        long long curr = 0;
        for (int i = pos; i < n; i++) {
            if (i > pos && num[pos] == '0') break;
            curr = curr * 10 + (num[i] - '0');
            if (pos == 0) {
                int saved = expr.size();
                expr.push_back(num[i]);
                backtrack(i + 1, curr, curr, expr);
                expr.resize(saved);
            } else {
                int saved = expr.size();
                expr.push_back('*');
                expr.push_back(num[i]);
                backtrack(i + 1, val - prev + prev * curr, prev * curr, expr);
                expr.resize(saved);
                expr.push_back('+');
                expr.push_back(num[i]);
                backtrack(i + 1, val + curr, curr, expr);
                expr.resize(saved);
                expr.push_back('-');
                expr.push_back(num[i]);
                backtrack(i + 1, val - curr, -curr, expr);
                expr.resize(saved);
            }
        }
    }

public:
    vector<string> addOperators(string num, int target) {
        res.clear();
        this->num = num;
        this->target = target;
        n = (int)num.size();
        string expr;
        backtrack(0, 0, 0, expr);
        return res;
    }
};
